//! Opens the synthetic public corpus (tests/corpus/public, generated by
//! scripts/make-fixtures.mjs) as documents, through the public API only.
#![allow(
    clippy::expect_used,
    clippy::panic,
    reason = "test helpers: a failed expectation is a test failure"
)]

use std::path::PathBuf;

use pdf_document::{Document, Rectangle};
use pdf_syntax::{Budget, CancellationToken, MemorySource, Object, ObjectId, ResourceLimits};

fn open(name: &str) -> Document<MemorySource> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/corpus/public")
        .join(name);
    let limits = ResourceLimits::default();
    let bytes = std::fs::read(&path).expect("fixture present");
    let source = MemorySource::from_vec(bytes, &limits).expect("within limits");
    Document::open(source, &mut Budget::new(limits, CancellationToken::new()))
        .unwrap_or_else(|e| panic!("{name}: {e}"))
}

fn id(number: u32) -> ObjectId {
    ObjectId {
        number,
        generation: 0,
    }
}

fn a4() -> Rectangle {
    Rectangle::new(0.0, 0.0, 595.0, 842.0)
}

#[test]
fn single_page_fixtures() {
    for name in ["minimal.pdf", "incremental.pdf"] {
        let doc = open(name);
        assert_eq!(doc.page_count(), 1, "{name}");
        let page = doc.page(0).expect("page");
        assert_eq!(page.id, id(3));
        assert_eq!(page.media_box, a4());
        assert_eq!(page.rotation, 0);
        assert_eq!(page.contents, Some(Object::Reference(id(4))));
        assert!(matches!(
            page.resources.as_deref(),
            Some(Object::Dictionary(_))
        ));
    }
}

#[test]
fn page_tree_fixture() {
    let doc = open("page-tree.pdf");
    let summary: Vec<(u32, f64, f64, u16)> = doc
        .pages()
        .iter()
        .map(|p| {
            (
                p.id.number,
                p.media_box.width(),
                p.media_box.height(),
                p.rotation,
            )
        })
        .collect();
    assert_eq!(
        summary,
        vec![
            (4, 595.0, 842.0, 90),
            (5, 842.0, 595.0, 90),
            (6, 595.0, 842.0, 0)
        ]
    );
    // Resources inherited from the root by every page, shared, not copied.
    let first = doc
        .page(0)
        .and_then(|p| p.resources.clone())
        .expect("resources");
    assert!(doc.pages().iter().all(|p| {
        p.resources
            .as_ref()
            .is_some_and(|r| std::sync::Arc::ptr_eq(r, &first))
    }));
    assert!(
        doc.pages()
            .iter()
            .all(|p| matches!(p.resources.as_deref(), Some(Object::Dictionary(_))))
    );
}
